insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:software-developer','2026-08-10',0,0,0,0,15,0,0,0,3,18,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Canonical Software Developer spans 009-01 web/open development, 009-02 embedded/control development, 009-03 programming and 009-99 other software-development work; no single code is fabricated.','entry_level_basis','Computing study, projects and practical software-development skills provide multiple entry routes; seven approved Japanese programmes are retained as direct study links.','market_scope','No exact recurring cross-country-comparable market series exists for the canonical umbrella.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:data-analyst','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The 2022 MHLW classification has no standalone Data Analyst code. Job tag places Data Scientist under 011-99, but Data Analyst is broader business-facing analytics and is not equated with Data Scientist.','entry_level_basis','Quantitative, computing, economics and business programmes are related pathways; eight approved programme links are retained only as related.','market_scope','Data-scientist or individual vacancy statistics are not reused as exact Data Analyst evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:data-engineer','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 010-99 explicitly lists データエンジニア and ビッグデータエンジニア.','entry_level_basis','Computer science and information programmes are common pathways, but production data-platform work often expects database, programming and cloud skills.','market_scope','010-99 is a broad residual IT group, so its statistics are not treated as Data Engineer-only evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:cybersecurity-analyst','2026-08-10',0,0,0,0,10,0,0,0,3,13,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Operational security analysts align to 010-04 IT system operations, while vulnerability-diagnosis security engineers are listed in 010-99; the canonical role spans both and therefore has no fabricated single code.','entry_level_basis','Computing programmes provide related preparation, while practical systems, network and security-operations skills remain important.','qualification_note','IPA information-security certifications are professional credentials, not a universal statutory licence to practise this occupation.','market_scope','Broader system-operations or residual-IT figures are not scored as exact cyber-analyst data.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:network-administrator','2026-08-10',0,0,0,0,15,0,0,0,3,18,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Job tag explicitly lists ネットワーク管理者 as an alternative title under 010-04 ITシステム運用管理者.','entry_level_basis','Networking and information-systems study plus hands-on server/network administration support entry; four approved programmes are retained as related.','qualification_note','Vendor and IPA certifications can support employability but are not a universal statutory licence.','market_scope','010-04 includes broader system administration, so group statistics are not treated as network-administrator-only evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:cloud-engineer','2026-08-10',0,0,0,0,10,0,0,0,3,13,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Cloud infrastructure design/build aligns to 010-02 ITシステム設計技術者, while ongoing cloud operations aligns to 010-04; the canonical role spans both.','entry_level_basis','Computer science and information programmes are related pathways, but cloud platform, networking, Linux and infrastructure experience are commonly needed.','qualification_note','Cloud-vendor and IPA credentials are optional professional signals, not a universal statutory licence.','market_scope','System-design and operations statistics are not merged into a fabricated Cloud Engineer series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:database-administrator','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Database administration is represented through 010-04 ITシステム運用管理者, restricted to database operations, access, backup, performance and reliability work.','entry_level_basis','Computing study is related preparation; practical database and systems-administration skills are important.','qualification_note','IPA Database Specialist and vendor credentials are not universal statutory licences.','market_scope','010-04 system-administration statistics are broader than DBA and remain unscored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:ict-support-technician','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 010-05 ITヘルプデスク directly covers internal help desk and technical user-support work.','entry_level_basis','The occupation can be entered through IT study, certifications and practical support experience; four approved programmes are retained as related pathways.','qualification_note','No universal statutory occupational licence is required.','market_scope','Published help-desk statistics are not yet normalised into the cross-country scoring model.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
